use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var kept_labels: List<String> = [];
    var i = 0;
    while i < planks.len() {
        match planks.get(i) {
            Some(plank) => {
                if mill.rules.is_kept(plank) {
                    kept_labels.push(mill.rules.label(plank));
                }
            },
            None => {},
        };
        i = i + 1;
    }
    kept_labels.join(sep: ",")
}

