use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let dishes = galley.menu.board();
    var i = 0;
    let len = dishes.len();
    while i < len {
        if i > 0 {
            io.write(text: ";")?;
        }
        match dishes.get(i) {
            Some(dish) => {
                galley.kitchen.serve(io: io, dish: dish)?;
            }
            None => {}
        }
        i = i + 1;
    }
    return Ok(unit);
}

use harbor.signal;

pub fn entries() -> String {
    let sigs = harbor.signal.signals();
    var parts: List<String> = [];
    var i = 0;
    while i < sigs.len() {
        let item = match sigs.get(i) {
            Some(s) => s,
            None => harbor.signal.Signal.Calm,
        };
        let rendered = match item {
            harbor.signal.Signal.Calm => "calm",
            harbor.signal.Signal.Gale(speed) => "gale:".concat(other: speed.to_text()),
            harbor.signal.Signal.Fog(word) => "fog:".concat(other: word),
        };
        parts.push(item: rendered);
        i = i + 1;
    }
    parts.join(sep: ";")
}

