use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let frame = match frames.get(index: i) {
            Some(f) => f,
            None => break,
        };
        let val = match relay.feed.decode(frame) {
            Ok(v) => v,
            Err(_) => 0,
        };
        total = total + val;
        i = i + 1;
    }
    relay.feed.emit(total: total, io: io)?;
    return Ok(unit);
}

