use depot.locker;

pub fn report() -> String {
    var ax = depot.locker.from_label("ax");
    var bay = depot.locker.from_label("bay");
    var cod = depot.locker.from_label("cod");

    ax.stow(12);
    ax.stow(9);

    bay.stow(30);
    bay.stow(25);

    cod.stow(5);

    let r_ax = ax.to_text();
    let r_bay = bay.to_text();
    let r_cod = cod.to_text();

    r_ax.concat(other: ",").concat(other: r_bay).concat(other: ",").concat(other: r_cod)
}

